import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as S from "./strings.ts";
import * as unicode from "./unicode.ts";

// Vectors generated by ts/tools/gen-strings-vectors from Go 1.21.13. Index-
// returning functions record the Go byte offset and the prefix s[:offset]; the
// UTF-16 result must equal prefix.length (or -1 when the prefix is null).

interface Vector {
  args: unknown[];
  want?: unknown;
  prefix?: string | null;
}

interface VectorFile {
  goVersion: string;
  seed: number;
  generator: string;
  functions: Record<string, Vector[]>;
}

const data: VectorFile = JSON.parse(
  readFileSync(new URL("./testdata/strings_vectors.json", import.meta.url), "utf8"),
);

const INDEX_FUNCTIONS = new Set(["Index", "LastIndex", "IndexByte", "IndexRune", "IndexAny"]);

function str(x: unknown): string {
  if (typeof x !== "string") {
    throw new TypeError(`expected string, got ${typeof x}`);
  }
  return x;
}

function num(x: unknown): number {
  if (typeof x !== "number") {
    throw new TypeError(`expected number, got ${typeof x}`);
  }
  return x;
}

// mapFn builds the mapping named in the vectors, with the same definition as
// the Go generator.
function mapFn(mode: string): (r: number) => number {
  switch (mode) {
    case "drop_space_control":
      return (r) => (unicode.IsSpace(r) || unicode.IsControl(r) ? -1 : r);
    case "upper":
      return unicode.ToUpper;
    case "invalid_out":
      return (r) => (r === 0x78 || r === 0x58 ? 0xd800 : r);
  }
  throw new Error(`unknown map mode ${mode}`);
}

interface BuilderOp {
  op: string;
  s?: string;
  n?: number;
}

function runBuilder(ops: BuilderOp[]): { string: string; len: number } {
  const b = new S.Builder();
  for (const o of ops) {
    switch (o.op) {
      case "WriteString":
        b.WriteString(str(o.s));
        break;
      case "WriteByte":
        b.WriteByte(num(o.n));
        break;
      case "WriteRune":
        b.WriteRune(num(o.n));
        break;
      case "Reset":
        b.Reset();
        break;
      case "Grow":
        b.Grow(num(o.n));
        break;
      default:
        throw new Error(`unknown builder op ${o.op}`);
    }
  }
  return { string: b.String(), len: b.Len() };
}

// calls maps each Go function name in the vectors to its TypeScript port.
const calls: Record<string, (a: unknown[]) => unknown> = {
  ReplaceAll: (a) => S.ReplaceAll(str(a[0]), str(a[1]), str(a[2])),
  Replace: (a) => S.Replace(str(a[0]), str(a[1]), str(a[2]), num(a[3])),
  Split: (a) => S.Split(str(a[0]), str(a[1])),
  SplitN: (a) => S.SplitN(str(a[0]), str(a[1]), num(a[2])),
  TrimSpace: (a) => S.TrimSpace(str(a[0])),
  Fields: (a) => S.Fields(str(a[0])),
  Trim: (a) => S.Trim(str(a[0]), str(a[1])),
  TrimLeft: (a) => S.TrimLeft(str(a[0]), str(a[1])),
  TrimRight: (a) => S.TrimRight(str(a[0]), str(a[1])),
  TrimPrefix: (a) => S.TrimPrefix(str(a[0]), str(a[1])),
  TrimSuffix: (a) => S.TrimSuffix(str(a[0]), str(a[1])),
  HasPrefix: (a) => S.HasPrefix(str(a[0]), str(a[1])),
  HasSuffix: (a) => S.HasSuffix(str(a[0]), str(a[1])),
  Index: (a) => S.Index(str(a[0]), str(a[1])),
  LastIndex: (a) => S.LastIndex(str(a[0]), str(a[1])),
  IndexByte: (a) => S.IndexByte(str(a[0]), num(a[1])),
  IndexRune: (a) => S.IndexRune(str(a[0]), num(a[1])),
  IndexAny: (a) => S.IndexAny(str(a[0]), str(a[1])),
  ContainsRune: (a) => S.ContainsRune(str(a[0]), num(a[1])),
  Contains: (a) => S.Contains(str(a[0]), str(a[1])),
  ContainsAny: (a) => S.ContainsAny(str(a[0]), str(a[1])),
  Count: (a) => S.Count(str(a[0]), str(a[1])),
  Cut: (a) => S.Cut(str(a[0]), str(a[1])),
  ToLower: (a) => S.ToLower(str(a[0])),
  ToUpper: (a) => S.ToUpper(str(a[0])),
  EqualFold: (a) => S.EqualFold(str(a[0]), str(a[1])),
  Map: (a) => S.Map(mapFn(str(a[0])), str(a[1])),
  Repeat: (a) => S.Repeat(str(a[0]), num(a[1])),
  Join: (a) => S.Join(a[0] as string[], str(a[1])),
  NewReplacer: (a) => S.NewReplacer(...(a[0] as string[])).Replace(str(a[1])),
  Builder: (a) => runBuilder(a[0] as BuilderOp[]),
};

test("every function in the vector file has a port", () => {
  for (const fn of Object.keys(data.functions)) {
    assert.ok(fn in calls, `no TypeScript port for ${fn}`);
  }
  assert.equal(Object.keys(data.functions).length, Object.keys(calls).length);
});

for (const [fn, cases] of Object.entries(data.functions)) {
  test(`strings.${fn} matches ${cases.length} Go vectors`, () => {
    assert.ok(cases.length >= 40, `${fn} has only ${cases.length} vectors`);
    const run = calls[fn];
    cases.forEach((c, k) => {
      const where = `${fn} case ${k} args=${JSON.stringify(c.args)}`;
      const got = run(c.args);
      if (INDEX_FUNCTIONS.has(fn)) {
        // The Go byte offset is replaced by the UTF-16 offset: the length of the
        // prefix that Go cut off.
        const want = c.prefix === null || c.prefix === undefined ? -1 : c.prefix.length;
        assert.equal(got, want, where);
      } else {
        assert.deepStrictEqual(got, c.want, where);
      }
    });
  });
}

// ---- hand-written checks ----------------------------------------------------

test("UTF-16 offsets: Go byte offsets are reported in code units", () => {
  assert.equal(S.Index("żółw", "w"), 3);
  assert.equal(S.LastIndex("żółw", "ó"), 1);
  assert.equal(S.IndexRune("😀x", 0x78), 2);
  assert.equal(S.IndexAny("日本語", "語"), 2);
  assert.equal(S.Count("abc", ""), 4);
  assert.equal(S.Count("😀", ""), 2);
});

test("TrimSpace and Fields use unicode.IsSpace: U+0085 and U+00A0 yes, U+200B and U+FEFF no", () => {
  assert.equal(S.TrimSpace("\u0085x "), "x");
  assert.equal(S.TrimSpace("​x﻿"), "​x﻿");
  assert.deepStrictEqual(S.Fields("a b​c\u0085d"), ["a", "b​c", "d"]);
});

test("ToLower and ToUpper map each rune with unicode.ToLower and ToUpper", () => {
  assert.equal(S.ToLower("İ"), "i");
  assert.equal(S.ToLower("İ ß"), "i ß");
  assert.equal(S.ToUpper("ß"), "ß");
  assert.equal(S.ToUpper("ǅ"), "Ǆ");
  assert.equal(S.ToLower("\u{10400}"), "\u{10428}");
});

test("EqualFold uses simple folding: Kelvin sign and long s fold, eszett does not fold to ss", () => {
  assert.equal(S.EqualFold("k", "K"), true);
  assert.equal(S.EqualFold("s", "ſ"), true);
  assert.equal(S.EqualFold("Straße", "STRASSE"), false);
  assert.equal(S.EqualFold("", ""), true);
  assert.equal(S.EqualFold("a", ""), false);
});

test("cutset functions treat the cutset as a set of runes", () => {
  assert.equal(S.Trim("😀a😀b😀", "😀"), "a😀b");
  assert.equal(S.TrimLeft("日本語日", "日"), "本語日");
  assert.equal(S.TrimRight("日本語日", "日"), "日本語");
  assert.equal(S.Trim("abc", ""), "abc");
});

test("Split and SplitN: empty separator splits into runes, n = 0 gives no pieces", () => {
  assert.deepStrictEqual(S.Split("😀a", ""), ["😀", "a"]);
  assert.deepStrictEqual(S.Split("", ""), []);
  assert.deepStrictEqual(S.Split("", ","), [""]);
  assert.deepStrictEqual(S.SplitN("a,b,c", ",", 0), []);
  assert.deepStrictEqual(S.SplitN("a,b,c", ",", 2), ["a", "b,c"]);
  assert.deepStrictEqual(S.SplitN("żó", "", 1), ["żó"]);
});

test("Replace with an empty old inserts at every rune boundary, including the ends", () => {
  // Go: strings.Replace("ż", "", "X", -1) == "XżX"
  assert.equal(S.ReplaceAll("ż", "", "X"), "XżX");
  assert.equal(S.ReplaceAll("", "", "X"), "X");
  assert.equal(S.Replace("ab", "", "X", 2), "XaXb");
  assert.equal(S.Replace("ab", "", "X", 0), "ab");
});

test("Replacer: first argument wins over longer keys, empty old matches between replacements", () => {
  assert.equal(S.NewReplacer("a", "1", "ab", "2").Replace("abc"), "1bc");
  assert.equal(S.NewReplacer("ab", "2", "a", "1").Replace("abc"), "2c");
  assert.equal(S.NewReplacer("a", "", "a", "X").Replace("aa"), "");
  assert.equal(S.NewReplacer("", "X", "a", "Y").Replace("ab"), "XYXbX");
  assert.equal(S.NewReplacer().Replace("abc"), "abc");
});

test("Replacer with an empty old on non-ASCII input: documented deviation from Go", () => {
  // Go steps one byte at a time, so for "ż" (two UTF-8 bytes) its output is
  // "X\xc5X\xbcX", which is not valid UTF-8 and cannot be a JS string. The port
  // inserts at code point boundaries instead.
  assert.equal(S.NewReplacer("", "X").Replace("ż"), "XżX");
  assert.equal(S.NewReplacer("", "X").Replace("😀b"), "X😀XbX");
});

test("Replacer does not rescan replacement text", () => {
  assert.equal(S.NewReplacer("a", "aa", "aa", "b").Replace("aa"), "aaaa");
});

test("Map drops runes for negative results and keeps U+FFFD", () => {
  assert.equal(S.Map(() => -1, "abc"), "");
  assert.equal(S.Map((r) => (r === 0x20 ? -1 : r), "a b 日"), "ab日");
  assert.equal(S.Map((r) => r, "�"), "�");
});

test("Repeat with a negative count throws, as Go panics", () => {
  assert.throws(() => S.Repeat("a", -1), /negative Repeat count/);
  assert.equal(S.Repeat("ż", 0), "");
});

test("NewReplacer with an odd argument count throws", () => {
  assert.throws(() => S.NewReplacer("a"), /odd argument count/);
});

test("IndexByte and Builder.WriteByte accept only ASCII bytes", () => {
  assert.equal(S.IndexByte("a:b", 0x3a), 1);
  assert.throws(() => S.IndexByte("abc", 0x80), /not representable/);
  assert.throws(() => new S.Builder().WriteByte(0xc5), /not representable/);
});

test("Builder returns Go's (n, err) shapes and reports UTF-8 byte length", () => {
  const b = new S.Builder();
  assert.deepStrictEqual(b.WriteString("żó"), [4, null]);
  assert.equal(b.WriteByte(0x21), null);
  assert.deepStrictEqual(b.WriteRune(0x1f600), [4, null]);
  assert.equal(b.Len(), 4 + 1 + 4);
  assert.equal(b.String(), "żó!😀");
  b.Grow(100);
  b.Reset();
  assert.equal(b.String(), "");
  assert.equal(b.Len(), 0);
  assert.throws(() => b.Grow(-1), /negative count/);
});

test("Builder.WriteRune writes U+FFFD for invalid runes", () => {
  const b = new S.Builder();
  b.WriteRune(0xd800);
  b.WriteRune(0x110000);
  assert.equal(b.String(), "��");
  assert.equal(b.Len(), 6);
});

// Unpaired surrogates stand for Go's invalid bytes. These checks must not throw
// and must follow the rules in the file header (adaptation 2).

test("unpaired surrogate: preserved by TrimSpace, Fields and Split", () => {
  assert.equal(S.TrimSpace("\ud800 x \udc00"), "\ud800 x \udc00");
  assert.deepStrictEqual(S.Fields("\ud800 x\udc00"), ["\ud800", "x\udc00"]);
  assert.deepStrictEqual(S.Split("a\ud800b", ""), ["a", "\ud800", "b"]);
  assert.equal(S.Index("a\ud800", "a"), 0);
});

test("unpaired surrogate: rewritten to U+FFFD by Map, ToLower and ToUpper, as Go rewrites invalid bytes", () => {
  assert.equal(S.ToLower("a\ud800b"), "a�b");
  assert.equal(S.ToUpper("\ud800"), "�");
  assert.equal(S.Map((r) => r, "\ud800"), "�");
  assert.equal(S.Map((r) => (r === 0xfffd ? -1 : r), "a\ud800b"), "ab");
  assert.equal(S.Map(() => -1, "a\ud800b"), "");
});

test("unpaired surrogate: counts as one rune and matches RuneError", () => {
  assert.equal(S.Count("\ud800\ud800", ""), 3);
  assert.equal(S.IndexRune("a\ud800", 0xfffd), 1);
  assert.equal(S.IndexRune("a\ud800", 0xd800), -1);
  assert.equal(S.IndexAny("ab\ud800", "�"), 2);
  assert.equal(S.EqualFold("\ud800", "�"), true);
});

test("unpaired surrogate: Replacer and Replace do not throw and keep the rest of the text", () => {
  assert.equal(S.NewReplacer("a", "1").Replace("a\ud800a"), "1\ud8001");
  assert.equal(S.ReplaceAll("\ud800x", "x", "y"), "\ud800y");
});

test("unpaired surrogate: Builder.WriteString counts it as 3 bytes, U+FFFD's length", () => {
  const b = new S.Builder();
  b.WriteString("\ud800");
  assert.equal(b.Len(), 3);
  assert.equal(b.String(), "\ud800");
});

test("unicode.IsSpace is the classifier TrimSpace uses (sanity)", () => {
  assert.equal(unicode.IsSpace(0x85), true);
  assert.equal(unicode.IsSpace(0x200b), false);
});
